def integrated_decide(store, memory, client, index):
    history = authenticated_projection(store, memory)
    context = incumbent.context(store, memory, index)
    if context['route']['route'] == 'MECHANICAL':
        return incumbent.canonical_action_decision(store, client, index, context)
    (s_action, suffix) = incumbent.escape_choice(store, memory, context['state'], context['assessments'])
    if suffix != context['suffix']:
        raise IntegrationInvariantError('S suffix changed during integration')
    e = recommendation(context, history)
    if s_action is not None and e['eligible']:
        raise IntegrationInvariantError('S and E simultaneously eligible')
    if s_action is not None:
        return incumbent.frozen_decide(store, memory, client, 'ACTIVE', 'S', index, context)
    if not e['eligible']:
        return incumbent.canonical_action_decision(store, client, index, context)
    action = e['target_action']
    if action not in context['candidate_set'] or e['source'] != empirical.SOURCE or e['reason'] != empirical.TRIGGER_REASON:
        raise IntegrationInvariantError('invalid E recommendation binding')
    route = {**context['route'], 'route': empirical.SOURCE, 'source': empirical.SOURCE, 'action': action, 'reason': empirical.TRIGGER_REASON}
    info = dict(call_id=None, raw_output_sha256=None, request_sha256=None, context_tokens=0, output_tokens=0, latency_seconds=0, status='NOT_CALLED')
    store.append('calls', 'ACTION_FROZEN', dict(decision_id=f'C:D{index:02d}', selected_action=action, decision_source=empirical.SOURCE, reason=empirical.TRIGGER_REASON, action_call_id=None, raw_output_sha256=None, candidate=e))
    store.save(state=context['state'], next_transaction_id=store.checkpoint['next_transaction_id'])
    return (action, empirical.SOURCE, route, info, context['assessments'], context['suffix'])

FROZEN_E_SHA256 = 'fcef478a02beb69a1d29988c5ce12929ad2ba077591131e0dcd114e7ccab99b4'

class IntegrationInvariantError(RuntimeError):
    """Abort selection without a model request or a world action."""

def authenticated_projection(store, memory):
    """Use SessionStore's existing authentication/replay, then reconcile Memory.

    Active events are admitted originals only. An out-of-band rejection journal
    has no active chronology contract, so reject it instead of dropping its tail
    or synthesizing a second event authority.
    """
    if not isinstance(store, SessionStore) or not isinstance(memory, ModernMemory):
        raise IntegrationInvariantError('E requires the active authenticated stores')
    if store._read_checkpoint() != store.checkpoint:
        raise IntegrationInvariantError('checkpoint changed before E projection')
    for name in store.STREAMS:
        if store._read_stream(name) != store.records[name]:
            raise IntegrationInvariantError('authenticated stream differs from live state')
    store._validate_checkpoint_heads()
    records = store.imported_history()
    memory.reconcile(store)
    for envelope in store.records['training']:
        record = envelope['record']
        if envelope['kind'] == 'REGISTERED_REJECTED_ATTEMPT' or ('authorization_status' in record and record['authorization_status'] != 'AUTHORIZED'):
            raise IntegrationInvariantError('non-authorized journal has no active event chronology')
    result = []
    for (envelope, event) in zip(store.records['events'], records):
        receipt = event['receipt']
        result.append(dict(event_stream_sequence=envelope['sequence'], authorization_status=event['authorization_status'], event_identity=canonical(event['receipt_identity']), receipt_identity=event['receipt_identity'], receipt_sha256=event['receipt_provenance_sha256'], state=receipt['pre_state'], action=receipt['action'], next_state=receipt['next_state'], consequence=receipt['realized_consequence']))
    if result and result[-1]['next_state'] != store.checkpoint['current_state']:
        raise IntegrationInvariantError('current state disagrees with authenticated receipt tail')
    return result

def recommendation(context, history):
    """No relation typing, evidence repair, model, world or Memory access."""
    if sha256(Path(candidate.__file__).read_bytes()).hexdigest() != FROZEN_E_SHA256:
        raise IntegrationInvariantError('frozen E source digest mismatch')
    try:
        return candidate.evaluate(context['state'], context['candidate_set'], context['assessments'], history)
    except (ValueError, KeyError, TypeError) as exc:
        raise IntegrationInvariantError('invalid E projection: ' + str(exc)) from exc

def previous_incumbent_decide(store, memory, client, index):
    """The exact canonical grounded-authority I decision path."""
    context = frozen.context(store, memory, index)
    return frozen.canonical_action_decision(store, client, index, context)

def promoted_decide(store, memory, client, index):
    """The evaluated S path: incumbent plus bounded stagnation escape."""
    context = frozen.context(store, memory, index)
    return frozen.frozen_decide(store, memory, client, 'ACTIVE', 'S', index, context)

THRESHOLD = 3

PURPOSE = 'ACQUIRE_MISSING_RELATION_EVIDENCE'

SOURCE = 'STAGNATION_ESCAPE'

def qualifying_suffix(store, memory):
    """Fail closed unless each counted signed decision replays against its receipt."""
    memory.reconcile(store)
    decisions = rows_of(store, 'AUTONOMOUS_AGENT_DECISION')
    rows = memory.rows()
    count = 0
    relation = None
    for d in reversed(decisions):
        seq = d.get('event_stream_sequence')
        if type(seq) is not int or seq < 1 or seq > len(store.records['events']):
            raise RuntimeError('decision event sequence missing')
        e = store.records['events'][seq - 1]['record']
        r = e['receipt']
        if e.get('authorization_status') != 'AUTHORIZED' or e.get('decision_index') != d['index'] or d['receipt_identity'] != e['receipt_identity'] or (d['receipt_provenance_sha256'] != e['receipt_provenance_sha256']) or (digest(r) != e['receipt_provenance_sha256']) or ((r['pre_state'], r['action'], r['next_state'], r['realized_consequence']) != (d['state'], d['selected_action'], d['realized']['next_state'], d['realized']['consequence'])):
            raise RuntimeError('decision/authorized receipt mismatch')
        for action in ACTIONS:
            if d['grounded_assessments_before'][action] != prior_state(rows, f"{d['state']}:{action}", seq):
                raise RuntimeError('predecision grounded replay mismatch')
        s = d['state']
        a = d['selected_action']
        assessment = d['grounded_assessments_before'][a]
        if relation is not None and relation != (s, a):
            break
        if not (d['decision_source'] == 'SAFE_GROUNDED_FALLBACK' and d['policy_route'] == 'MODEL' and (d['action_parse_status'] == 'VALID') and (assessment['relation_type'] == 'DETERMINISTIC') and (assessment['kind'] == 'ESTABLISHED') and (assessment['established_value']['consequence'] == 0) and any((x != a and d['grounded_assessments_before'][x]['kind'] == 'UNSEEN' for x in ACTIONS)) and all((not (x['relation_type'] == 'DETERMINISTIC' and x['kind'] == 'ESTABLISHED' and (x['established_value']['consequence'] == 1)) for x in d['grounded_assessments_before'].values())) and (r['next_state'] == s) and (r['realized_consequence'] == 0)):
            break
        relation = (s, a)
        count += 1
    return dict(count=count, relation=None if relation is None else list(relation))

def escape_choice(store, memory, state, assessments):
    suffix = qualifying_suffix(store, memory)
    if suffix['count'] < THRESHOLD or suffix['relation'] is None or suffix['relation'][0] != state:
        return (None, suffix)
    fallback = suffix['relation'][1]
    selected = assessments[fallback]
    route = select_route(assessments)
    if route['route'] != 'MODEL' or selected['relation_type'] != 'DETERMINISTIC' or selected['kind'] != 'ESTABLISHED' or (selected['established_value']['consequence'] != 0) or any((v == 1 for v in route['known_values'].values())):
        return (None, suffix)
    unseen = [a for a in ACTIONS if a != fallback and assessments[a]['kind'] == 'UNSEEN']
    if not unseen:
        return (None, suffix)
    action = unseen[0]
    if action not in route['candidates']:
        raise RuntimeError('unseen action outside incumbent mixed route')
    return (action, suffix)

NAME = 'BOUNDED_EMPIRICAL_EVIDENCE_ACQUISITION'

SHORT_ID = 'E'

SOURCE = 'EMPIRICAL_EVIDENCE_ACQUISITION'

TRIGGER_REASON = 'DETERIORATED_EMPIRICAL_RELATION_WITH_MISSING_EVIDENCE'

WINDOW = 4

ACTIONS = ('ADVANCE', 'HOLD', 'RETREAT')

EMPIRICAL_KINDS = ('EMPIRICALLY_STABLE', 'VARIABLE_RELATION')

def _consequence(value):
    if type(value) is not int or value not in (-1, 0, 1):
        raise ValueError('invalid realized consequence')
    return value

def _outcome(value):
    if not isinstance(value, dict) or type(value.get('next_state')) is not int:
        raise ValueError('invalid observed next state')
    return (value['next_state'], _consequence(value.get('consequence')))

def empirical_component(assessment, observed_outcomes):
    """Exact H2 empirical signal, using only this relation's prior observations.

    This component is also usable on relation-only control traces; it does not
    assert that an unseen alternative or an admissible action set exists there.
    """
    if not isinstance(assessment, dict) or not isinstance(observed_outcomes, (list, tuple)):
        raise ValueError('invalid empirical input')
    observed = tuple((_outcome(x) for x in observed_outcomes))
    recent = tuple((_outcome(x) for x in assessment.get('recent_window', ())))
    if type(assessment.get('observation_count')) is not int or assessment['observation_count'] != len(observed):
        raise ValueError('grounded count disagrees with verified history')
    if recent != observed[-WINDOW:]:
        raise ValueError('grounded recent window disagrees with verified history')
    recent_sum = sum((x[1] for x in recent))
    cumulative_sum = sum((x[1] for x in observed))
    kind = assessment.get('kind')
    signal = kind in EMPIRICAL_KINDS and assessment.get('possible_change') is None and (len(recent) == WINDOW) and (recent_sum <= 0) and (cumulative_sum <= 0)
    return dict(signal=signal, recent_sum=recent_sum, cumulative_sum=cumulative_sum, observation_count=len(observed), empirical_kind=kind)

def _checked_history(history):
    if not isinstance(history, (list, tuple)):
        raise ValueError('history must be a complete ordered event sequence')
    for (expected_sequence, event) in enumerate(history, 1):
        if not isinstance(event, dict) or event.get('event_stream_sequence') != expected_sequence:
            raise ValueError('history has an omitted, duplicated, or unordered event')
        if event.get('authorization_status') != 'AUTHORIZED':
            continue
        if not event.get('event_identity') or not event.get('receipt_identity') or (not isinstance(event.get('receipt_sha256'), str)) or (fullmatch('[0-9a-f]{64}', event['receipt_sha256']) is None) or (type(event.get('state')) is not int) or (type(event.get('next_state')) is not int) or (event.get('action') not in ACTIONS):
            raise ValueError('authorized event lacks verified projection fields')
        _consequence(event.get('consequence'))
    return history

def evaluate(current_state, admissible_actions, assessments, history):
    """Return a prospective recommendation; never select/execute an actual action.

    `history` includes every pre-decision event in order, including non-authorized
    events, and is supplied by the existing authenticated replay boundary.
    Invalid/incomplete projections raise ValueError, so no acquisition is returned.
    """
    if type(current_state) is not int:
        raise ValueError('invalid current state')
    if not isinstance(admissible_actions, (list, tuple)) or not admissible_actions or len(set(admissible_actions)) != len(admissible_actions) or any((a not in ACTIONS for a in admissible_actions)):
        raise ValueError('invalid admissible action set')
    if not isinstance(assessments, dict) or any((a not in assessments for a in admissible_actions)):
        raise ValueError('missing grounded assessment')
    _checked_history(history)
    last = history[-1] if history else None
    repeated_action = last.get('action') if last and last.get('authorization_status') == 'AUTHORIZED' else None
    relation = [current_state, repeated_action] if repeated_action else None
    suffix = []
    if repeated_action in admissible_actions:
        for event in reversed(history):
            if event.get('authorization_status') != 'AUTHORIZED' or event.get('state') != current_state or event.get('next_state') != current_state or (event.get('action') != repeated_action):
                break
            suffix.append(event)
    suffix.reverse()
    count = len(suffix)
    base = dict(candidate=NAME, short_id=SHORT_ID, eligible=False, target_action=None, source=None, reason='NO_TRIGGER', qualifying_relation=relation, suffix_count=count, recent_sum=None, cumulative_sum=None, unseen_candidates=[])
    if count < WINDOW:
        return base
    selected = assessments[repeated_action]
    if not isinstance(selected, dict) or selected.get('relation_type') != 'EMPIRICAL' or selected.get('kind') not in EMPIRICAL_KINDS or (selected.get('possible_change') is not None) or (selected.get('relation') != f'{current_state}:{repeated_action}'):
        return base
    all_observed = [dict(next_state=e['next_state'], consequence=e['consequence']) for e in history if e.get('authorization_status') == 'AUTHORIZED' and e.get('state') == current_state and (e.get('action') == repeated_action)]
    empirical = empirical_component(selected, all_observed)
    base['recent_sum'] = empirical['recent_sum']
    base['cumulative_sum'] = empirical['cumulative_sum']
    if not empirical['signal']:
        return base
    if tuple((_outcome(x) for x in all_observed[-WINDOW:])) != tuple(((e['next_state'], e['consequence']) for e in suffix[-WINDOW:])):
        raise ValueError('recent relation observations disagree with consecutive suffix')
    for action in admissible_actions:
        assessment = assessments[action]
        if not isinstance(assessment, dict) or assessment.get('relation') != f'{current_state}:{action}':
            raise ValueError('assessment does not match current relation')
        if assessment.get('relation_type') == 'DETERMINISTIC' and assessment.get('kind') == 'ESTABLISHED' and isinstance(assessment.get('established_value'), dict) and (assessment['established_value'].get('consequence') == 1):
            return base
    unseen = [action for action in ACTIONS if action in admissible_actions and action != repeated_action and (assessments[action].get('kind') == 'UNSEEN') and (assessments[action].get('observation_count') == 0)]
    base['unseen_candidates'] = unseen
    if not unseen:
        return base
    return {**base, 'eligible': True, 'target_action': unseen[0], 'source': SOURCE, 'reason': TRIGGER_REASON}

def value(row):
    return dict(next_state=row['realized_next_state'], consequence=row['realized_consequence'])

def fold(rows):
    state = dict(kind='UNSEEN', established_value=None, candidate_value=None, candidate_count=0, established_support=[], candidate_support=[], alternatives=[], receipt_provenance=[])
    for row in rows:
        if row['authorization_status'] != 'AUTHORIZED' or not row['event_identity'] or (not row['receipt_provenance_sha256']):
            raise RuntimeError('unauthenticated state input')
        identity = row['event_identity']
        observed = value(row)
        state['receipt_provenance'].append(dict(identity=identity, value=observed, receipt_sha256=row['receipt_provenance_sha256'], event_stream_sequence=row['event_stream_sequence']))
        if state['kind'] == 'UNSEEN':
            state.update(kind='ESTABLISHED', established_value=observed, established_support=[identity])
        elif state['kind'] == 'ESTABLISHED':
            if observed == state['established_value']:
                state['established_support'].append(identity)
            else:
                state.update(kind='UNRESOLVED_CHANGE', candidate_value=observed, candidate_count=1, candidate_support=[identity], alternatives=[])
        elif observed == state['established_value']:
            state.update(kind='ESTABLISHED', candidate_value=None, candidate_count=0, candidate_support=[], alternatives=[], established_support=state['established_support'] + [identity])
        elif observed == state['candidate_value']:
            state['candidate_count'] += 1
            state['candidate_support'].append(identity)
            state.update(kind='ESTABLISHED', established_value=observed, established_support=state['candidate_support'][:], candidate_value=None, candidate_count=0, candidate_support=[], alternatives=[])
        else:
            prior = dict(value=state['candidate_value'], support=state['candidate_support'][:])
            state['alternatives'].append(prior)
            state.update(candidate_value=observed, candidate_count=1, candidate_support=[identity])
    return state

WINDOW = 4

MIN_PRIOR = 6

def key(v):
    return f"{v['next_state']}:{v['consequence']}"

def counts(values):
    tally = Counter((key(v) for v in values))
    return dict(sorted(tally.items()))

def modal(values):
    tally = Counter((key(v) for v in values))
    return max(tally, key=lambda k: (tally[k], -next((i for (i, v) in enumerate(values) if key(v) == k)))) if values else None

def fold(rows):
    outcomes = []
    provenance = []
    segment_start = 0
    pending = None
    confirmed = []
    for row in rows:
        if row['authorization_status'] != 'AUTHORIZED' or not row['event_identity'] or (not row['receipt_provenance_sha256']) or (not row['event_stream_sequence']):
            raise RuntimeError('unauthenticated empirical input')
        observed = value(row)
        outcomes.append(observed)
        provenance.append(dict(identity=row['event_identity'], receipt_sha256=row['receipt_provenance_sha256'], event_stream_sequence=row['event_stream_sequence'], value=observed))
        if pending:
            if key(observed) == pending['challenger']:
                segment_start = pending['candidate_start']
                confirmed.append(dict(candidate_start=segment_start, confirmed_at=len(outcomes) - 1, support=[p['identity'] for p in provenance[segment_start:]]))
            pending = None
            continue
        segment = outcomes[segment_start:]
        if len(segment) < MIN_PRIOR + WINDOW:
            continue
        earlier = segment[:-WINDOW]
        recent = segment[-WINDOW:]
        challenger = key(recent[0])
        if len(earlier) >= MIN_PRIOR and all((key(v) == challenger for v in recent)) and (challenger != modal(earlier)):
            pending = dict(challenger=challenger, candidate_start=len(outcomes) - WINDOW, prior_counts=counts(earlier), recent_counts=counts(recent), recent_support=[p['identity'] for p in provenance[-WINDOW:]])
    current = outcomes[segment_start:]
    kind = 'UNSEEN' if not outcomes else 'POSSIBLE_REGIME_CHANGE' if pending else 'EMPIRICALLY_STABLE' if len(counts(current)) == 1 else 'VARIABLE_RELATION'
    return dict(kind=kind, observation_count=len(outcomes), outcome_counts=counts(outcomes), chronological_outcomes=outcomes, receipt_provenance=provenance, recent_window=outcomes[-WINDOW:], window_limit=WINDOW, segment_start=segment_start, segment_counts=counts(current), empirical_frequencies={k: dict(count=n, denominator=len(current)) for (k, n) in counts(current).items()}, segment_mode=modal(current), possible_change=pending, confirmed_changes=confirmed)

def point(state, current_state):
    mode = state['segment_mode']
    if mode is None:
        return dict(next_state=current_state, consequence=0)
    (next_state, consequence) = map(int, mode.split(':'))
    return dict(next_state=next_state, consequence=consequence)

class AuthenticatedMemory:
    """Adapter to the frozen SessionStore + ModernMemory admission/reconcile path.

    A caller must first append the protected original receipt event to SessionStore.
    `append` then invokes ModernMemory.record, which validates current signed event
    provenance. Derivation always reconciles the durable stores before reading.
    """

    def __init__(self, store, memory):
        self.store = store
        self.memory = memory

    def append(self, event_envelope: dict, context_identifier: str) -> dict:
        admission = self.memory.record(self.store, event_envelope, context_identifier)
        self.memory.reconcile(self.store)
        return admission

    def rows(self, relation: RelationKey) -> list[dict]:
        if not isinstance(relation, RelationKey):
            raise TypeError('RelationKey required')
        self.memory.reconcile(self.store)
        return self.memory.rows(relation.storage_key)

def derive_relation_state(memory: AuthenticatedMemory, relation_key: RelationKey, relation_type: RelationType) -> DerivedRelationState:
    if not isinstance(memory, AuthenticatedMemory):
        raise TypeError('AuthenticatedMemory required')
    if not isinstance(relation_key, RelationKey):
        raise TypeError('RelationKey required')
    if not isinstance(relation_type, RelationType):
        raise ValueError('explicit RelationType required')
    rows = memory.rows(relation_key)
    state = deterministic.fold(rows) if relation_type is RelationType.DETERMINISTIC else empirical.fold(rows)
    provenance = tuple((ReceiptProvenance(p['identity'], p['receipt_sha256'], p['event_stream_sequence'], p['value']['next_state'], p['value']['consequence']) for p in state['receipt_provenance']))
    if len(provenance) != len(rows):
        raise RuntimeError('state omitted receipt provenance')
    return DerivedRelationState(relation_key, relation_type, state['kind'], json.dumps(state, sort_keys=True, separators=(',', ':')), provenance)

def assess_relation(relation_key: RelationKey, state: DerivedRelationState, optional_model_generalization: Any=None) -> RelationAssessment:
    if relation_key != state.relation:
        raise ValueError('assessment relation mismatch')
    if state.kind == 'UNSEEN':
        status = 'UNSEEN'
    elif state.kind in ('UNRESOLVED_CHANGE', 'POSSIBLE_REGIME_CHANGE'):
        status = 'UNRESOLVED'
    else:
        status = 'GROUNDED'
    return RelationAssessment(relation_key, state.relation_type, status, state.kind, state._evidence_json, state.provenance, optional_model_generalization if status == 'UNSEEN' else None, False)

CEILING = 1

KNOWN = 'ESTABLISHED'

UNCERTAIN_KINDS = ('UNSEEN', 'UNRESOLVED_CHANGE', 'EMPIRICALLY_STABLE', 'VARIABLE_RELATION', 'POSSIBLE_REGIME_CHANGE')

def known_value(assessment):
    if assessment['relation_type'] == 'DETERMINISTIC' and assessment['kind'] == KNOWN:
        value = assessment['established_value']
        if not isinstance(value, dict) or type(value.get('consequence')) is not int:
            raise ValueError('invalid authenticated established value')
        return value['consequence']
    if assessment['kind'] not in UNCERTAIN_KINDS:
        raise ValueError('unregistered grounded kind: ' + assessment['kind'])
    return None

def select_route(assessments):
    if set(assessments) != set(ACTIONS):
        raise ValueError('assessment/action mismatch')
    values = {action: known_value(assessments[action]) for action in ACTIONS}
    ceiling = [action for action in ACTIONS if values[action] == CEILING]
    if ceiling:
        return dict(route='MECHANICAL', source='GROUNDED_MECHANICAL', action=ceiling[0], candidates=[ceiling[0]], known_values=values, reason='ESTABLISHED_GLOBAL_CEILING')
    known = [action for action in ACTIONS if values[action] is not None]
    unknown = [action for action in ACTIONS if values[action] is None]
    if not unknown:
        best = max(values.values())
        action = next((a for a in ACTIONS if values[a] == best))
        return dict(route='MECHANICAL', source='GROUNDED_MECHANICAL', action=action, candidates=[action], known_values=values, reason='ALL_ACTIONS_ESTABLISHED')
    best_known = None if not known else next((a for a in ACTIONS if values[a] == max((values[x] for x in known))))
    candidates = [a for a in ACTIONS if a == best_known or a in unknown]
    return dict(route='MODEL', source=None, action=None, candidates=candidates, known_values=values, reason='UNCERTAINTY_REMAINS')
